def transpose_matrix(grid):
    if not grid or not grid[0]:
        return []
    return [[row[i] for row in grid] for i in range(len(grid[0]))]

def rotate_90_clockwise(grid):
    if not grid or not grid[0]:
        return []
    return [list(row) for row in zip(*grid[::-1])]

def rotate_90_counterclockwise(grid):
    if not grid or not grid[0]:
        return []
    return [list(row) for row in zip(*grid)][::-1]

def column_sums(grid):
    if not grid or not grid[0]:
        return []
    return [sum(row[c] for row in grid) for c in range(len(grid[0]))]

def count_value_neighbours(grid, r, c, value):
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    count = 0
    for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
        nr, nc = r + dr, c + dc
        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == value:
            count += 1
    return count

def largest_region_size(grid):
    if not grid or not grid[0]:
        return 0
    rows, cols = len(grid), len(grid[0])
    seen = [[False] * cols for _ in range(rows)]
    best = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1 and not seen[i][j]:
                stack = [(i, j)]
                seen[i][j] = True
                size = 0
                while stack:
                    x, y = stack.pop()
                    size += 1
                    for dx, dy in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] == 1 and not seen[nx][ny]:
                            seen[nx][ny] = True
                            stack.append((nx, ny))
                best = max(best, size)
    return best

def main_diagonal(grid):
    if not grid or not grid[0]:
        return []
    n = min(len(grid), len(grid[0]))
    return [grid[i][i] for i in range(n)]

def anti_diagonal(grid):
    if not grid or not grid[0]:
        return []
    rows, cols = len(grid), len(grid[0])
    k = min(rows, cols)
    return [grid[i][cols - 1 - i] for i in range(k)]

def spiral_order(grid):
    if not grid or not grid[0]:
        return []
    res = []
    top, bottom = 0, len(grid) - 1
    left, right = 0, len(grid[0]) - 1
    while top <= bottom and left <= right:
        for c in range(left, right + 1):
            res.append(grid[top][c])
        top += 1
        for r in range(top, bottom + 1):
            res.append(grid[r][right])
        right -= 1
        if top <= bottom:
            for c in range(right, left - 1, -1):
                res.append(grid[bottom][c])
            bottom -= 1
        if left <= right:
            for r in range(bottom, top - 1, -1):
                res.append(grid[r][left])
            left += 1
    return res

def border_elements(grid):
    if not grid or not grid[0]:
        return []
    rows, cols = len(grid), len(grid[0])
    res = []
    for i in range(rows):
        for j in range(cols):
            if i == 0 or i == rows - 1 or j == 0 or j == cols - 1:
                res.append(grid[i][j])
    return res

def equal_under_rotation(grid1, grid2):
    def rot(g):
        if not g or not g[0]:
            return []
        return [list(row) for row in zip(*g[::-1])]
    g = grid1
    for _ in range(4):
        if g == grid2:
            return True
        g = rot(g)
    return False

def max_value_position(grid):
    best = None
    pos = None
    for i, row in enumerate(grid):
        for j, v in enumerate(row):
            if best is None or v > best:
                best = v
                pos = (i, j)
    return pos

def is_symmetric_matrix(grid):
    rows = len(grid)
    if rows == 0:
        return True
    cols = len(grid[0])
    if rows != cols:
        return False
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] != grid[j][i]:
                return False
    return True

def row_with_max_sum(grid):
    best_i, best_sum = 0, sum(grid[0])
    for i in range(1, len(grid)):
        s = sum(grid[i])
        if s > best_sum:
            best_sum = s
            best_i = i
    return best_i

def column_with_max_sum(grid):
    cols = len(grid[0])
    sums = [sum(row[c] for row in grid) for c in range(cols)]
    best_i = 0
    for c in range(1, cols):
        if sums[c] > sums[best_i]:
            best_i = c
    return best_i
